    },
  },
  scope: {
    appName: process.env.MODAL_APP_NAME!,
    environment: process.env.MODAL_ENVIRONMENT ?? "main",
  },
  timeout: 120_000,
});

const sandbox = await client.create({
  source: { image: { reference: "alpine:3.21" } },
  runtime: {
    workingDirectory: "/tmp",
    entrypoint: ["sleep", "infinity"],
    pty: true,
  },
  isolation: { kind: IsolationKind.Container },
  resources: { cpuCores: 0.5, memoryMib: 512n },
  network: { egress: EgressMode.AllowAll },
  lifetime: {
    maximumLifetime: 5 * 60_000,
    idleTerminate: { mode: PolicyMode.After, after: 60_000 },
  },
  labels: { example: "use-modal-files" },
});

const localDir = await mkdtemp(join(tmpdir(), "sandbox-kit-files-"));
try {
  const remoteDir = "/tmp/kit-files";
  const remote = `${remoteDir}/note.txt`;
  const body = new TextEncoder().encode("hello from sandbox-kit\n");
  await sandbox.filesystem.makeDirectory(remoteDir);
  await sandbox.filesystem.writeFile(remote, body);
  const data = await sandbox.filesystem.readFile(remote);
  const info = await sandbox.filesystem.stat(remote);
  const entries = await sandbox.filesystem.listDirectory(remoteDir);
  const local = join(localDir, "note.txt");
  await sandbox.filesystem.copyToLocal(remote, local);
  const copied = await readFile(local);
  if (Buffer.compare(copied, Buffer.from(data)) !== 0) {
    throw new Error("local copy does not match the remote file");
  }
  const remoteCopy = `${remoteDir}/copy.txt`;
  await sandbox.filesystem.copyFromLocal(local, remoteCopy);
  await sandbox.filesystem.remove(remoteCopy);
  await sandbox.filesystem.remove(remoteDir, { recursive: true });
